export function workspaceFor(view,domain,preferred){
 const matches=LEARNING_WORKSPACES.filter(w=>w.groups.some(g=>g.views.includes(view)));
 const byDomain={vehicle:'vehicle',power:'energy',track:'track',control:'track',station:'station',communications:'information',operations:'information',depot:'maintenance'};
 return matches.find(w=>w.id===preferred)||matches.find(w=>w.id===byDomain[domain])||matches[0]||null;
}
export function workspaceRoute(id){return LEARNING_WORKSPACES.find(w=>w.id===id)?.view||null;}
// A concept picker and a physical hierarchy serve different jobs. Keep one
// named occurrence per row, omit incompatible configurations, and reveal
// descendants progressively. Searching still finds a closed assembly's parts.
export function assemblyTreeRows(inspection,{expanded=new Set(),filter=''}={}){
 const all=new Map((inspection?.tree||[]).map(n=>[n.instanceId,n]));
 const nodes=[...all.values()].filter(n=>n.conceptId&&n.available!==false),ids=new Set(nodes.map(n=>n.instanceId)),parents=new Map(),children=new Map();
 for(const n of nodes){let parent=all.get(n.parentAssemblyId),seen=new Set([n.instanceId]);while(parent&&!ids.has(parent.instanceId)&&!seen.has(parent.instanceId)){seen.add(parent.instanceId);parent=all.get(parent.parentAssemblyId);}const id=parent&&ids.has(parent.instanceId)?parent.instanceId:null;parents.set(n.instanceId,id);if(id)children.set(id,(children.get(id)||0)+1);}
 const query=filter.trim().toLowerCase(),matches=new Set(nodes.filter(n=>!query||`${n.label} ${n.function||''} ${n.role||''}`.toLowerCase().includes(query)).map(n=>n.instanceId)),shown=new Set(matches);
 if(query)for(const id of matches){let parent=parents.get(id),seen=new Set([id]);while(parent&&!seen.has(parent)){shown.add(parent);seen.add(parent);parent=parents.get(parent);}}
 return nodes.filter(n=>{if(query)return shown.has(n.instanceId);let parent=parents.get(n.instanceId),seen=new Set([n.instanceId]);while(parent&&!seen.has(parent)){if(!expanded.has(parent))return false;seen.add(parent);parent=parents.get(parent);}return true;}).map(n=>({...n,hasChildren:children.has(n.instanceId),expanded:query?true:expanded.has(n.instanceId),matches:matches.has(n.instanceId),treeParent:parents.get(n.instanceId)}));
}
export function applyAnatomyQuery(state,query){
 const text=key=>{const value=query.get(key);return value&&value.length<=600&&!/[\u0000-\u001f]/.test(value)?value:null;};
 state.instanceId=text('instance');state.functionalPath=text('trace');state.studyId=text('study');
 state.allInstances=query.get('instances')==='all';
 const preferred=text('workspace');state.workspace=LEARNING_WORKSPACES.some(w=>w.id===preferred)?preferred:null;
 const mode=query.get('inspect');
 if(mode==='assembled'||mode==='section'){state.cutaway=mode==='section';state.exploded=0;state.explodeScope='all';}
 if(mode==='staged'){state.cutaway=false;state.explodeScope='selected';const value=Number(query.get('exposure')||1);state.exploded=Number.isFinite(value)?Math.max(0,Math.min(1,value)):1;}
 return state;
}
export function writeAnatomyQuery(url,state,defaultCutaway=false){
 for(const [key,value] of [['instance',state.instanceId],['trace',state.functionalPath],['study',state.studyId],['workspace',state.workspace]]){if(value)url.searchParams.set(key,value);else url.searchParams.delete(key);}
 const staged=state.explodeScope==='selected'&&state.exploded>0;
 if(state.allInstances)url.searchParams.set('instances','all');else url.searchParams.delete('instances');
 const mode=staged?'staged':state.cutaway!==defaultCutaway?(state.cutaway?'section':'assembled'):null;
 if(mode)url.searchParams.set('inspect',mode);else url.searchParams.delete('inspect');
 if(staged&&state.exploded<1)url.searchParams.set('exposure',String(state.exploded));else url.searchParams.delete('exposure');
 return url;
}
